-- Fixed Agenda application adapters and a transactional user-scoped pin service.
-- All newly registered mutations remain unexposed/unverified; no messages/models are invoked here.
BEGIN;
CREATE TABLE public.sandy_api_agenda_pin_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 actor_id uuid NOT NULL,
 customer_id uuid NOT NULL,
 before_task_ids uuid[] NOT NULL,
 after_task_ids uuid[] NOT NULL,
 occurred_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.sandy_api_agenda_pin_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.sandy_api_agenda_pin_events FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.sandy_api_pin_audit_immutable() RETURNS trigger LANGUAGE plpgsql
SET search_path=pg_catalog,pg_temp AS $immutable$
BEGIN RAISE EXCEPTION 'sandy_agenda_pin_audit_append_only' USING ERRCODE='23514'; END $immutable$;
REVOKE ALL ON FUNCTION public.sandy_api_pin_audit_immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER sandy_api_pin_audit_immutable BEFORE UPDATE OR DELETE ON public.sandy_api_agenda_pin_events
FOR EACH ROW EXECUTE FUNCTION public.sandy_api_pin_audit_immutable();

CREATE FUNCTION public.sandy_api_agenda_save_pins(p_task_ids uuid[]) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $pins$
DECLARE v_actor_id uuid:=auth.uid(); v_customer_id uuid; v_portal_ids uuid[]; before_ids uuid[]; matched integer;
BEGIN
 -- Derive every tenant/actor from the actual authenticated request; service-role
 -- or Controller administration is not a substitute for this customer session.
 v_customer_id:=public.sandy_api_current_agenda_customer_id();
 IF v_actor_id IS NULL OR v_customer_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','customer_session_required','http_status',403); END IF;
 SELECT array_agg(p.customer_id) INTO v_portal_ids FROM public.sandy_memory_portal_accounts p
 JOIN auth.users u ON u.id=p.auth_user_id AND u.email_confirmed_at IS NOT NULL
 JOIN public.email_customer_addresses a ON a.customer_id=p.customer_id AND a.is_primary=true AND a.normalized_email=lower(u.email)
 WHERE p.auth_user_id=v_actor_id AND p.revoked_at IS NULL;
 IF cardinality(v_portal_ids) IS DISTINCT FROM 1 OR v_portal_ids[1] IS DISTINCT FROM v_customer_id THEN RETURN jsonb_build_object('ok',false,'error','matching_portal_agenda_grants_required','http_status',403); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry r WHERE r.operation='agenda.pins.save' AND r.handler='sandy-operation-api' AND r.permission_scope='tasks:write' AND r.is_mutation=true AND r.api_exposed=true AND r.verified=true) THEN
 RETURN jsonb_build_object('ok',false,'error','operation_requires_live_verification','http_status',424); END IF;
 IF p_task_ids IS NULL OR coalesce(array_ndims(p_task_ids),1)<>1 THEN
 RETURN jsonb_build_object('ok',false,'error','invalid_pinned_tasks','http_status',400); END IF;
 IF cardinality(p_task_ids)>100 OR array_position(p_task_ids,NULL) IS NOT NULL
 OR (SELECT count(DISTINCT x) FROM unnest(p_task_ids) x)<>cardinality(p_task_ids) THEN
 RETURN jsonb_build_object('ok',false,'error','invalid_pinned_tasks','http_status',400); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('agenda_pins:'||v_customer_id::text,0));
 -- Share locks protect ownership/archive/readback until replacement commits.
 PERFORM t.id FROM public.sandy_tasks t WHERE t.id=ANY(p_task_ids) AND t.customer_id=v_customer_id AND t.archived_at IS NULL ORDER BY t.id FOR SHARE;
 GET DIAGNOSTICS matched=ROW_COUNT;
 IF matched<>cardinality(p_task_ids) THEN RETURN jsonb_build_object('ok',false,'error','owned_unarchived_tasks_required','http_status',403); END IF;
 SELECT coalesce(array_agg(p.task_id ORDER BY p.position,p.task_id),ARRAY[]::uuid[]) INTO before_ids FROM public.sandy_task_pins p WHERE p.customer_id=v_customer_id;
 IF before_ids=p_task_ids THEN RETURN jsonb_build_object('ok',true,'task_ids',to_jsonb(p_task_ids),'reused',true); END IF;
 DELETE FROM public.sandy_task_pins p WHERE p.customer_id=v_customer_id;
 INSERT INTO public.sandy_task_pins(customer_id,task_id,position)
 SELECT v_customer_id,v.task_id,(v.position-1)::integer FROM unnest(p_task_ids) WITH ORDINALITY v(task_id,position);
 INSERT INTO public.sandy_api_agenda_pin_events(actor_id,customer_id,before_task_ids,after_task_ids)
 VALUES(v_actor_id,v_customer_id,before_ids,p_task_ids);
 RETURN jsonb_build_object('ok',true,'task_ids',to_jsonb(p_task_ids),'reused',false);
END $pins$;
REVOKE ALL ON FUNCTION public.sandy_api_agenda_save_pins(uuid[]) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_api_agenda_save_pins(uuid[]) TO authenticated;

